[{"order":1,"type":"heading","text":"Mastering Dynamic Blocks and Meta-Arguments in Terraform"},{"order":2,"type":"paragraph","text":"Infrastructure as Code requires flexibility and DRY (Don't Repeat Yourself) principles. Terraform provides powerful features like meta-arguments (count, for_each) and dynamic blocks to help you manage complex configurations efficiently without duplicating code."},{"order":3,"type":"subheading","text":"1. Using the count Meta-Argument"},{"order":4,"type":"paragraph","text":"The count meta-argument accepts a whole number and creates that many instances of a resource or module. Each instance is indexed using the 'count.index' object."},{"order":5,"type":"code","text":"resource "aws_instance" "server" {
  count         = 3
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"

  tags = {
    Name = "Server-${count.index + 1}"
  }
}"},{"order":6,"type":"subheading","text":"2. Using the for_each Meta-Argument"},{"order":7,"type":"paragraph","text":"While count uses integer indexes, for_each accepts a map or a set of strings. This is much safer for resource management because removing or reordering elements in a map does not cause all subsequent resources to be destroyed and recreated."},{"order":8,"type":"code","text":"resource "aws_iam_user" "developer" {
  for_each = toset(["alice", "bob", "charlie"])
  name     = each.key
}"},{"order":9,"type":"subheading","text":"3. Generating Content with Dynamic Blocks"},{"order":10,"type":"paragraph","text":"Some Terraform resources require repeated nested blocks (like ingress rules in security groups or setting blocks in load balancers). The dynamic block allows you to iterate over a complex data structure to generate these nested blocks programmatically."},{"order":11,"type":"code","text":"variable "ingress_rules" {
  type = list(object({
    port        = number
    description = string
  }))
  default = [
    { port = 80, description = "HTTP" },
    { port = 443, description = "HTTPS" }
  ]
}

resource "aws_security_group" "web" {
  name = "web_sg"

  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
      description = ingress.value.description
    }
  }
}"},{"order":12,"type":"subheading","text":"4. Controlling Resource Lifecycles"},{"order":13,"type":"paragraph","text":"Meta-arguments inside the 'lifecycle' block allow you to modify the default behavior of Terraform during updates and destruction. Common lifecycle arguments include create_before_destroy, prevent_destroy, and ignore_changes."},{"order":14,"type":"code","text":"resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"

  lifecycle {
    create_before_destroy = true
    prevent_destroy       = false
    ignore_changes        = [tags]
  }
}"},{"order":15,"type":"bullet_point","text":"create_before_destroy ensures zero-downtime deployments by provisioning the new resource before deleting the old one."},{"order":16,"type":"bullet_point","text":"prevent_destroy acts as a safety guard against accidental terraform destroy execution on critical production infrastructure."},{"order":17,"type":"bullet_point","text":"ignore_changes tells Terraform to skip drift detection on specific attributes (like auto-scaled tags or passwords managed outside Terraform)."}]
